import subprocess, os, tempfile

def handle(query, state):
    flag = state.get("flag", "")
    flag_file = os.path.join(tempfile.gettempdir(), "credentials.db")
    with open(flag_file, "w") as f:
        f.write(flag)
    search_term = (query.get("q") or [""])[0]
    if not search_term:
        return 200, {"Content-Type": "text/plain"}, "Usage: ?q=<search_term>"
    try:
        result = subprocess.check_output(
            f"grep -r '{search_term}' /var/log",
            shell=True,
            stderr=subprocess.STDOUT,
            timeout=5
        )
        return 200, {"Content-Type": "text/plain"}, result.decode("utf-8", errors="replace")
    except subprocess.CalledProcessError as e:
        output = e.output.decode("utf-8", errors="replace")
        if "Permission denied" in output or "No such" in output:
            return 200, {"Content-Type": "text/plain"}, "Search completed with warnings"
        return 200, {"Content-Type": "text/plain"}, output
    except Exception as e:
        return 500, {"Content-Type": "text/plain"}, str(e)
